export const MATHEMATICS_SESSION_FLOW = [
  { minutes: 2, name: 'The verse, read aloud' },
  { minutes: 8, name: 'The lesson, with the working shown' },
  { minutes: 6, name: 'Try it with your hands' },
  { minutes: 4, name: 'The check — a game you can redo' },
];
export const MATHEMATICS_SESSION_MINUTES = MATHEMATICS_SESSION_FLOW.reduce((t, s) => t + s.minutes, 0);

export const MATHEMATICS_INTEREST_TAG = '[Mathematics interest]';
export const MATHEMATICS_HELPER_TAG = '[Mathematics helper]';

export function resolveMathematicsCohort(localCohort = null) {
  return resolveCohortGeneric(localCohort, MATHEMATICS_CONFIRMED_COHORT, MATHEMATICS_PROPOSED_COHORT_START);
}

// Self-paced: one row per lesson, no painted date.
export function buildMathematicsSchedule() {
  return MATHEMATICS_MODULES.map((m, i) => ({ ...m, week: i + 1, date: null, weekday: null }));
}

export function mathematicsProgressSummary(progress = {}) {
  return progressSummaryFor(MATHEMATICS_MODULES, progress);
}

export function exportMathematicsCurriculumMarkdown() {
  return exportCurriculumMarkdownFor(
    { meta: MATHEMATICS_META, sessionFlow: MATHEMATICS_SESSION_FLOW, modules: MATHEMATICS_MODULES },
    null,
  );
}

// Ari for mathematics: show the working, every number from the Word, never a
// guessed figure, and the honest line between what the Word records and what
// mathematics adds beside it.
export const MATHEMATICS_TUTOR_META = {
  title: MATHEMATICS_META.title,
  intro: 'You are Ari, a patient mathematics helper for a school-age learner (about 6 to 11) working through Word-based mathematics in "Mathematics — Counting, Measure and Reason from the Word."',
  posture: 'Show the working, one step per line, in short sentences. Every number you teach with comes from this lesson or from a Bible verse quoted in it; never invent a figure and never round a Bible number to something it does not say. When mathematics adds something beside the Word (a formula, a decimal, a name like ratio), say plainly that the Word records the measure and mathematics gives it that name. If the learner is wrong, say the right answer gently, show why, and let them try again — the check is a game they can redo. Say Yahweh for the Father, and Jesus for the Son. Keep every answer under five sentences.',
};
